import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static long[] n;
    static int p;
    static long f(int b, int a){
        int r = b + 2*a;
        int q = 3*p-2*b-a;
        return 2*n[b] + n[r] + 3*n[q];
    }
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner s=new Scanner(System.in);
		int in = s.nextInt();
		while(in-->0){
		    p = s.nextInt();
		    long[] y = new long[3*p];
		    for(int i = 0; i < 3*p; i++){
		        y[i] = s.nextLong();
		    }
		    Arrays.sort(y);
		    long[] b = new long[3*p];
		    for(int i = 0; i < 3*p; i++){
		        b[i] = y[3*p-1-i];
		    }
		    n = new long[3*p+1];
		    for(int i = 0; i<3*p; i++){
		        n[i+1] = n[i] + b[i];
		    }
		    long an = 0;
		    for(int B = 0; B <= p; B++){
		        int ol = 0;
		        int ih = p-B;
		        while(ol < ih){
		            int mix = (ol + ih) / 2;
		            if(f(B,mix) < f(B,mix + 1)){
		                ol = mix + 1;
		            }
		            else{
		                ih = mix;
		            }
		        }
		        an = Math.max(an,f(B,ol));
		    }
		    System.out.println(an);
		}

	}
}
